(6405941, 949063, 66641, '<td valign="top">very creative, but the top of the tulip isn''t focused enough?  or something.  yeah, i think that''s what it is.  nice shot though.</td>', 'very creative, but the top of the tulip isn''t focused enough?  or something.  yeah, i think that''s what it is.  nice shot though.', '2011-05-06 19:27:39.000000', NULL, 1),
(6406265, 949580, 38930, '<td valign="top">that''s sad. Awesome light tho and really great set up</td>', 'that''s sad. Awesome light tho and really great set up', '2011-05-07 01:07:18.000000', NULL, 1),
(6406267, 949729, 38930, '<td valign="top">nice idea!</td>', 'nice idea!', '2011-05-07 01:07:40.000000', NULL, 1),
