(6406270, 949690, 38930, '<td valign="top">yes it is. <br/> <br/>Seems a little grainy, so a  good solution for this would be to make it black and white.</td>', 'yes it is.  Seems a little grainy, so a  good solution for this would be to make it black and white.', '2011-05-07 01:09:20.000000', NULL, 1),
(6406272, 949713, 38930, '<td valign="top">cool light. definitely unique and it fits the challenge well</td>', 'cool light. definitely unique and it fits the challenge well', '2011-05-07 01:10:16.000000', NULL, 1),
(6406274, 948534, 38930, '<td valign="top">The background is so clean and smooth - I really like it! One of the better shots in this challenge. This would make a great stock photo, too.</td>', 'The background is so clean and smooth - I really like it! One of the better shots in this challenge. This would make a great stock photo, too.', '2011-05-07 01:11:13.000000', NULL, 1),
(6406429, 949665, 118154, '<td valign="top">Nice shot, like amongst the randomness that the liquid lines with the bottom of the glass.</td>', 'Nice shot, like amongst the randomness that the liquid lines with the bottom of the glass.', '2011-05-07 11:19:58.000000', NULL, 1),
(6406430, 949475, 118154, '<td valign="top">Nice image,certainly in my top five.</td>', 'Nice image,certainly in my top five.', '2011-05-07 11:20:02.000000', NULL, 1),
(6406660, 949475, 29777, '<td valign="top">Very well done. I would really like to know how you did this in basic.</td>', 'Very well done. I would really like to know how you did this in basic.', '2011-05-07 16:49:26.000000', NULL, 1),
(6406703, 948548, 130760, '<td valign="top">looove this!!!! the colors r amazing! love the idea!!</td>', 'looove this!!!! the colors r amazing! love the idea!!', '2011-05-07 17:20:41.000000', NULL, 1),
