(6410214, 949420, 52549, '<td valign="top">Very creative idea and well carried out (love that water drop ;-). Many congrats on your ribbon, Anthony.</td>', 'Very creative idea and well carried out (love that water drop ;-). Many congrats on your ribbon, Anthony.', '2011-05-11 03:13:59.000000', NULL, 0),
(6410219, 949628, 93421, '<td valign="top">Congrats on a well-deserved ribbon Irene!  Lovely to have you back.  Hope all is well!</td>', 'Congrats on a well-deserved ribbon Irene!  Lovely to have you back.  Hope all is well!', '2011-05-11 03:18:58.000000', NULL, 0),
(6410233, 949628, 96751, '<td valign="top">Yaaaay Irene!!!  Yes, you are a technical marvel with the glass, but the part that I''m simply in awe of is the seamless edge of the background.  Hope you don''t mind sharing how you did that!!!</td>', 'Yaaaay Irene!!!  Yes, you are a technical marvel with the glass, but the part that I''m simply in awe of is the seamless edge of the background.  Hope you don''t mind sharing how you did that!!!', '2011-05-11 03:35:45.000000', NULL, 0),
